const learnerRequirementTypes=['Subject tuition','Skill development','NEET coaching','JEE coaching','School admission','College admission','Other'];
function requirementQuestions(type,slot){const prefix=slot+'_'+type.toLowerCase().replace(/[^a-z]+/g,'_')+'_';const f=(key,label,t='text',options=[],required=true)=>field(prefix+key,label,t,options,required);let list=[];
if(type==='School admission')list=[f('class','Class / grade seeking admission'),f('year','Academic year / intake'),f('board','Preferred board / curriculum','select',['CBSE','ICSE / ISC','State board','IB','Cambridge','Montessori / preschool','Open to options','Other']),f('location','Preferred city / locality'),f('budget','Annual tuition-fee budget (INR, or undecided)'),f('distance','Maximum travel distance (km)','number',[],false),f('transport','School transport needed?','select',['Yes','No','Undecided']),f('hostel','Day school / residential preference','select',['Day school','Residential / hostel','Either']),f('facilities','Facilities, activities and learning support expected','textarea'),f('start','Desired joining / admission timeline'),f('shortlist','Preferred institutions, if any','textarea',[],false)];
else if(type==='College admission')list=[f('level','Level of study','select',['Diploma','Undergraduate','Postgraduate','Doctoral','Certificate','Other']),f('programme','Preferred course / programme / specialisation'),f('qualification','Current / completed qualification'),f('year','Academic year / intake'),f('location','Preferred city / region'),f('budget','Annual tuition-fee budget (INR, or undecided)'),f('mode','Study mode','select',['Full-time on campus','Part-time','Online / distance','Open to options']),f('hostel','Hostel required?','select',['Yes','No','Undecided']),f('entrance','Entrance exam / admission eligibility details (if relevant)','textarea',[],false),f('priorities','Institution expectations: facilities, accreditation, support, etc.','textarea'),f('start','Application / joining timeline'),f('shortlist','Preferred institutions, if any','textarea',[],false)];
else {list=[f('focus',type==='Subject tuition'?'Subjects and topics needing support':type==='Skill development'?'Skills / course you want to learn':type==='Other'?'Describe your requirement':'Subjects or areas needing exam support','textarea'),...(type==='Subject tuition'?[f('grade','Class / level and curriculum')]:[]),...(['NEET coaching','JEE coaching'].includes(type)?[f('examYear','Target exam year'),f('examTrack','Preparation stage','select',['Foundation','First attempt','Repeater','Revision / test series']),...(type==='JEE coaching'?[f('exam','Target examination','select',['JEE Main','JEE Advanced','Both'])]:[])]:[]),f('goals','Goals and expected outcomes','textarea'),f('mode','Preferred learning mode','select',['Online','In person','Hybrid','Flexible']),f('location','Preferred locality (or online)'),f('language','Preferred teaching language'),f('timing','Preferred days and times'),f('frequency','Preferred sessions / classes per week','text'),f('format','Class format','select',['One-to-one','Small group','Batch classes','Flexible']),f('trial','Trial / introductory session preference','select',['Preferred','Not required','Open to provider policy']),f('budget','Budget amount / range (INR, or undecided)'),f('budgetUnit','Budget period','select',['Per session','Per month','Per course']),f('start','When would you like to start?','select',['Immediately','Within one month','Within three months','Exploring options'])];}
return list.map((q,i)=>({...q,requirementHeading:i===0?(slot==='main'?'Main requirement: ':'Second requirement: ')+type:null}));}
const fieldsBeforeLearnerNeeds=adaptiveFields;
adaptiveFields=function(id){if(state.role!=='learner'||id!=='preferences')return fieldsBeforeLearnerNeeds(id);const f=record().fields,main=f.needs,second=f.secondNeed;return [field('needs','Main requirement','select',learnerRequirementTypes,true),field('secondNeed','Second requirement','select',['No second requirement',...learnerRequirementTypes.filter(t=>t!==main)],false),...(learnerRequirementTypes.includes(main)?requirementQuestions(main,'main'):[]),...(learnerRequirementTypes.includes(second)&&second!==main?requirementQuestions(second,'second'):[])]};
const fieldBeforeNeedHeadings=fieldHTML;fieldHTML=function(q){return (q.requirementHeading?`<div class="full requirement-heading"><h3>${esc(q.requirementHeading)}</h3><p class="muted">Preferences for this requirement are kept separately.</p></div>`:'')+fieldBeforeNeedHeadings(q)};
const profileBeforeLearnerNeeds=profile;profile=function(){profileBeforeLearnerNeeds();if(state.role!=='learner'||steps()[registration.step]?.id!=='preferences')return;for(const key of ['needs','secondNeed']){const select=$('#registration-form select[name="'+key+'"]');if(select)select.onchange=()=>{saveFields();if(record().fields.needs===record().fields.secondNeed){record().fields.secondNeed='No second requirement';toast('Choose a different second requirement.')}profile()}}};
const missingBeforeSecondNeed=missingFields;missingFields=function(){const m=missingBeforeSecondNeed();if(state.role==='learner'){const f=record().fields;if(!learnerRequirementTypes.includes(f.needs))m.push('Valid main requirement');if(f.secondNeed&&f.secondNeed!=='No second requirement'&&(!learnerRequirementTypes.includes(f.secondNeed)||f.secondNeed===f.needs))m.push('A different valid second requirement')}return m};
if(location.hash==='#profile')render();
